# main.tf
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

resource "aws_s3_bucket" "tenant_docs" {
  bucket = "vc-assistant-${var.tenant_id}-docs"
  tags   = { Tenant = var.tenant_id, Env = var.environment }
}

resource "aws_kms_key" "tenant_key" {
  description = "KMS key for tenant ${var.tenant_id}"
}

